     * same householdId) has 3 or more members; otherwise 'SILVER' when namesakeCount is 0
     * and an email is present, else 'BRONZE'.
     */
    protected OwnerDto.MembershipTierEnum toMembershipTier(Owner owner) {
        if (isGoldHousehold(owner)) {
            return OwnerDto.MembershipTierEnum.GOLD;
        }
        Integer namesakeCount = owner.getNamesakeCount();
        String email = owner.getEmail();
        boolean hasEmail = email != null && !email.isBlank();
        return (namesakeCount != null && namesakeCount == 0 && hasEmail)
                ? OwnerDto.MembershipTierEnum.SILVER : OwnerDto.MembershipTierEnum.BRONZE;
    }

    /** Whether the owner's household has enough members to reach the 'GOLD' tier. */
    private boolean isGoldHousehold(Owner owner) {
        String householdId = owner.getHouseholdId();
        if (householdId == null) {
            return false;
        }
        long members = ownerRepository.findAll().stream()
                .filter(existing -> householdId.equals(existing.getHouseholdId()))
                .count();
        return members >= GOLD_HOUSEHOLD_SIZE;
    }

