package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects a create whose lastName and address already belong to an existing owner
 * (see {@link OwnerHousehold} for the membership rule). A clash is rejected 409 via
 * {@link DuplicateHouseholdException}, unless the request opts in with
 * {@code sharesHousehold} true — in which case {@link AssignOwnerHousehold} gives the
 * housemates a shared id.
 */
public class EnsureUniqueOwnerHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        // Opt-in flag lets known housemates share a lastName and address.
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (OwnerHousehold.isSameHousehold(request.getLastName(), request.getAddress(), existing)) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of household membership, shared by {@link EnsureUniqueOwnerHousehold}
 * (which rejects an unshared duplicate) and {@link AssignOwnerHousehold} (which assigns the
 * shared id), so the guard and the assignment agree by construction rather than by comment.
 * Two owners are in the same household when their lastName and address match. lastName is
 * compared case-insensitively with collapsed whitespace; address is compared using the
 * shared {@link AddressNormalizer} form, so the guard and the assignment agree with the
 * address that is stored and returned.
 */
final class OwnerHousehold {

    private OwnerHousehold() {
    }

    /** Whether an owner with the given lastName and address shares a household with {@code other}. */
    static boolean isSameHousehold(String lastName, String address, Owner other) {
        return normalize(lastName).equals(normalize(other.getLastName()))
                && AddressNormalizer.normalize(address).equals(AddressNormalizer.normalize(other.getAddress()));
    }

    /** Lower-case and collapse whitespace runs to a single space for comparison. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

